pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint256[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        vm.assume(_tos.length < 50);
        for (uint256 i = 0; i < v.length; i++) {
            v[i] = bound(v[i], 0, type(uint256).max / 1000000000000000000);
        }
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        bool success;
        try c.transfer(_tos, v) returns (bool ret) {
            success = true;
            assertTrue(ret == true);
        } catch {
            success = false;
        }
        if (success) {
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address[] memory _tos, uint[] memory v) public payable {
        require(msg.sender != 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        bool reverted; try c.transfer(_tos, v) { reverted = false; } catch { reverted = true; }
        assert(reverted == true);
    }
    receive() external payable {}
}

